#!/bin/sh
# Run simulation: build the Verilator harness and run all suites.
#
# The suites are checked against the pinned vectors in tb/vectors/, which
# were generated by scripts/generate_vectors.py (pyDes cross-checked against
# OpenSSL; see tb/vectors/SHA256SUMS).
#
# Usage: sh design/amd_am9518/scripts/run_sim.sh
set -eu

SCRIPT_DIR=$(CDPATH= cd -- "$(dirname -- "$0")" && pwd)
DESIGN_DIR=$(dirname "$SCRIPT_DIR")
WORK_DIR="$DESIGN_DIR/work/sim"
OBJ_DIR="$WORK_DIR/obj_dir"

mkdir -p "$WORK_DIR"

VERILATOR=${VERILATOR:-verilator}

"$VERILATOR" \
    --cc --exe --build -j 0 -O2 \
    --top-module amd_am9518_top \
    --Mdir "$OBJ_DIR" -I"$DESIGN_DIR/src" \
    "$DESIGN_DIR/src/des_core.sv" \
    "$DESIGN_DIR/src/amd_am9518_top.sv" \
    "$DESIGN_DIR/tb/amd_am9518_harness.cpp" \
    -o amd_am9518_harness 2>&1 | tee "$WORK_DIR/build.log"

"$OBJ_DIR/amd_am9518_harness" --vectors "$DESIGN_DIR/tb/vectors" "$@"
